    public byte[] compress(byte[] input, int offset, int length) {
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public byte[] decompress(byte[] input, int offset, int length, int uncompressedLength) {
        throw new UnsupportedOperationException("Not implemented");
    }
}

